// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.faceimport com.google.mlkit.vision.common.InputImageimport com.google.mlkit.vision.face.Faceimport com.google.mlkit.vision.face.FaceContourimport com.google.mlkit.vision.face.FaceDetectionimport com.google.mlkit.vision.face.FaceDetector as MlKitFaceDetectorClientimport com.google.mlkit.vision.face.FaceDetectorOptionsimport com.google.mlkit.vision.face.FaceLandmarkimport com.roshan.persona.vision.ocr.BoundingBoximport com.roshan.persona.vision.ocr.RgbImageimport com.roshan.persona.vision.ocr.toBitmapimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — ML Kit Face Detector (Module 6 v4 — Step 6.4, REAL implementation). * * Wraps `com.google.mlkit:face-detection` for on-device face DETECTION (not * recognition — hard privacy line, see [FacePrivacyGuard]). * * Implements [FaceDetectorDelegate] so it slots into the same Hilt graph as * the (hypothetical) TFLite face delegate. * * ## Privacy * *  - **DETECTION ONLY.** Returns bounding boxes + landmarks + contours + *    smile/eye probabilities — never identifies who the faces belong to. *  - No face-embedding model in the APK. *  - All inference is on-device via ML Kit (no cloud API). * * ## Performance * *  - < 80 ms per frame on mid-range devices (ML Kit on-device). *  - Real-time: 12-20 FPS face tracking (vs 30 FPS object detection — face *    detection is heavier per-frame). * * @see <a href="https://developers.google.com/ml-kit/vision/face-detection/android">ML Kit Face Detection</a> */@Singletonclass MlKitFaceDetector @Inject constructor() : FaceDetectorDelegate {    /**     * Lazily-built per-options detector cache. ML Kit's [MlKitFaceDetectorClient]     * is configured at construction time with the landmark/contour/classification     * modes; we cache one client per options signature to avoid rebuilding.     */    private val detectorCache = mutableMapOf<String, MlKitFaceDetectorClient>()    @Volatile    private var ready: Boolean = true    override suspend fun detect(frame: RgbImage, options: FaceDetectionOptions): List<DetectedFace> {        if (!ready || frame.width <= 0 || frame.height <= 0) return emptyList()        val bitmap = try {            frame.toBitmap()        } catch (t: Throwable) {            Timber.tag("NOUS.Vision").e(t, "Failed to convert RgbImage to Bitmap")            return emptyList()        }        return try {            val detector = detectorFor(options)            val inputImage = InputImage.fromBitmap(bitmap, 0)            // 10s timeout to prevent ANR if Google Play Services hangs.            val mlFaces = com.google.android.gms.tasks.Tasks.await(                detector.process(inputImage),                10,                java.util.concurrent.TimeUnit.SECONDS,            )            val width = frame.width.toFloat().coerceAtLeast(1f)            val height = frame.height.toFloat().coerceAtLeast(1f)            mlFaces.map { face ->                val rect = face.boundingBox                val left = (rect.left.toFloat() / width).coerceIn(0f, 0.999f)                val top = (rect.top.toFloat() / height).coerceIn(0f, 0.999f)                val right = (rect.right.toFloat() / width).coerceIn(left + 0.001f, 1f)                val bottom = (rect.bottom.toFloat() / height).coerceIn(top + 0.001f, 1f)                val boundingBox = try {                    BoundingBox(left = left, top = top, right = right, bottom = bottom)                } catch (iae: IllegalArgumentException) {                    Timber.tag("NOUS.Vision").w(iae, "Skipping face with invalid bbox: $rect")                    return@map null                }                val landmarks = if (options.landmarkExtraction) {                    extractLandmarks(face, width, height)                } else {                    null                }                val contours = if (options.contourExtraction) {                    extractContours(face, width, height)                } else {                    null                }                DetectedFace(                    boundingBox = boundingBox,                    confidence = DEFAULT_FACE_CONFIDENCE,                    landmarks = landmarks,                    contours = contours,                    smileProbability = if (options.smileDetection) face.smilingProbability else null,                    leftEyeOpenProbability = if (options.eyeOpenDetection) face.leftEyeOpenProbability else null,                    rightEyeOpenProbability = if (options.eyeOpenDetection) face.rightEyeOpenProbability else null,                    headEulerAngleX = if (options.headAngleDetection) face.headEulerAngleX else null,                    headEulerAngleY = if (options.headAngleDetection) face.headEulerAngleY else null,                    headEulerAngleZ = if (options.headAngleDetection) face.headEulerAngleZ else null,                )            }.filterNotNull()        } catch (t: Throwable) {            Timber.tag("NOUS.Vision").e(t, "ML Kit FaceDetection failed")            emptyList()        } finally {            bitmap.recycle()        }    }    override fun isReady(): Boolean = ready    // ─── Internal ──────────────────────────────────────────────────────────    private fun detectorFor(options: FaceDetectionOptions): MlKitFaceDetectorClient {        val key = "${options.landmarkExtraction}|${options.contourExtraction}|" +            "${options.smileDetection}|${options.eyeOpenDetection}|${options.headAngleDetection}"        return detectorCache.getOrPut(key) {            val builder = FaceDetectorOptions.Builder()                .setPerformanceMode(FaceDetectorOptions.PERFORMANCE_MODE_ACCURATE)                .setMinFaceSize(MIN_FACE_SIZE)            if (options.landmarkExtraction) {                builder.setLandmarkMode(FaceDetectorOptions.LANDMARK_MODE_ALL)            } else {                builder.setLandmarkMode(FaceDetectorOptions.LANDMARK_MODE_NONE)            }            if (options.contourExtraction) {                builder.setContourMode(FaceDetectorOptions.CONTOUR_MODE_ALL)            } else {                builder.setContourMode(FaceDetectorOptions.CONTOUR_MODE_NONE)            }            if (options.smileDetection || options.eyeOpenDetection) {                builder.setClassificationMode(FaceDetectorOptions.CLASSIFICATION_MODE_ALL)            } else {                builder.setClassificationMode(FaceDetectorOptions.CLASSIFICATION_MODE_NONE)            }            builder.build().let { FaceDetection.getClient(it) }        }    }    /** Extract facial landmarks (normalized 0.0-1.0) from an ML Kit [Face]. */    private fun extractLandmarks(face: Face, width: Float, height: Float): FaceLandmarks {        fun landmarkPoint(type: Int): LandmarkPoint? {            val lm = face.getLandmark(type) ?: return null            val x = (lm.position.x / width).coerceIn(0f, 1f)            val y = (lm.position.y / height).coerceIn(0f, 1f)            return try {                LandmarkPoint(x, y)            } catch (iae: IllegalArgumentException) {                null            }        }        return FaceLandmarks(            leftEye = landmarkPoint(FaceLandmark.LEFT_EYE),            rightEye = landmarkPoint(FaceLandmark.RIGHT_EYE),            leftEar = landmarkPoint(FaceLandmark.LEFT_EAR),            rightEar = landmarkPoint(FaceLandmark.RIGHT_EAR),            noseBase = landmarkPoint(FaceLandmark.NOSE_BASE),            mouthLeft = landmarkPoint(FaceLandmark.MOUTH_LEFT),            mouthRight = landmarkPoint(FaceLandmark.MOUTH_RIGHT),            mouthBottom = landmarkPoint(FaceLandmark.MOUTH_BOTTOM),            leftCheek = landmarkPoint(FaceLandmark.LEFT_CHEEK),            rightCheek = landmarkPoint(FaceLandmark.RIGHT_CHEEK),        )    }    /** Extract face contours (normalized 0.0-1.0) from an ML Kit [Face]. */    private fun extractContours(face: Face, width: Float, height: Float): FaceContours {        fun contourPoints(type: Int): List<LandmarkPoint> {            val contour = face.getContour(type) ?: return emptyList()            return contour.points.mapNotNull { p ->                val x = (p.x / width).coerceIn(0f, 1f)                val y = (p.y / height).coerceIn(0f, 1f)                try {                    LandmarkPoint(x, y)                } catch (iae: IllegalArgumentException) {                    null                }            }        }        return FaceContours(            faceOval = contourPoints(FaceContour.FACE),            leftEyeContour = contourPoints(FaceContour.LEFT_EYE),            rightEyeContour = contourPoints(FaceContour.RIGHT_EYE),            leftEyebrowTop = contourPoints(FaceContour.LEFT_EYEBROW_TOP),            leftEyebrowBottom = contourPoints(FaceContour.LEFT_EYEBROW_BOTTOM),            rightEyebrowTop = contourPoints(FaceContour.RIGHT_EYEBROW_TOP),            rightEyebrowBottom = contourPoints(FaceContour.RIGHT_EYEBROW_BOTTOM),            noseBridge = contourPoints(FaceContour.NOSE_BRIDGE),            noseBottom = contourPoints(FaceContour.NOSE_BOTTOM),            upperLipTop = contourPoints(FaceContour.UPPER_LIP_TOP),            upperLipBottom = contourPoints(FaceContour.UPPER_LIP_BOTTOM),            lowerLipTop = contourPoints(FaceContour.LOWER_LIP_TOP),            lowerLipBottom = contourPoints(FaceContour.LOWER_LIP_BOTTOM),        )    }    private companion object {        private const val TAG = "MlKitFaceDetector"        // ML Kit FaceDetector doesn't expose per-face confidence — it either        // detects a face (high confidence) or doesn't. Use 0.95.        private const val DEFAULT_FACE_CONFIDENCE = 0.95f        // Minimum face size (proportion of image) — 0.15 = 15% of image dimension.        // Smaller than this is rarely useful for downstream landmark/contour work.        private const val MIN_FACE_SIZE = 0.15f    }}